import math
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch as th
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication and softmax fusion
matmul_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_softmax_kernel(const float* x, const float* clusters, float* out, int rows, int cols, int clusters_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < rows * clusters_size) {
        int row = idx / clusters_size;
        int col = idx % clusters_size;
        float sum = 0.0f;
        for (int i = 0; i < cols; ++i) {
            sum += x[row * cols + i] * clusters[i * clusters_size + col];
        }
        out[idx] = sum;
    }
}

torch::Tensor matmul_softmax_cuda(torch::Tensor x, torch::Tensor clusters) {
    auto rows = x.size(0);
    auto cols = x.size(1);
    auto clusters_size = clusters.size(1);
    auto out = torch::zeros({rows, clusters_size}, x.options());

    const int block_size = 256;
    const int num_blocks = (rows * clusters_size + block_size - 1) / block_size;

    matmul_softmax_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), clusters.data_ptr<float>(), out.data_ptr<float>(), rows, cols, clusters_size);

    return out;
}
"""

matmul_softmax_cpp_source = (
    "torch::Tensor matmul_softmax_cuda(torch::Tensor x, torch::Tensor clusters);"
)

# Compile the inline CUDA code for matrix multiplication and softmax fusion
matmul_softmax = load_inline(
    name="matmul_softmax",
    cpp_sources=matmul_softmax_cpp_source,
    cuda_sources=matmul_softmax_source,
    functions=["matmul_softmax_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, cluster_size, feature_size, ghost_clusters):
        super(ModelNew, self).__init__()

        self.feature_size = feature_size
        self.cluster_size = cluster_size
        self.ghost_clusters = ghost_clusters

        init_sc = (1 / math.sqrt(feature_size))
        clusters = cluster_size + ghost_clusters

        # The `clusters` weights are the `(w,b)` in the paper
        self.clusters = nn.Parameter(init_sc * th.randn(feature_size, clusters))
        self.batch_norm = nn.BatchNorm1d(clusters)
        # The `clusters2` weights are the visual words `c_k` in the paper
        self.clusters2 = nn.Parameter(init_sc * th.randn(1, feature_size, cluster_size))
        self.out_dim = self.cluster_size * feature_size
        self.matmul_softmax = matmul_softmax

    def forward(self, x, mask=None):
        """Aggregates feature maps into a fixed size representation.  In the following
        notation, B = batch_size, N = num_features, K = num_clusters, D = feature_size.

        Args:
            x (th.Tensor): B x N x D

        Returns:
            (th.Tensor): B x DK
        """
        max_sample = x.size()[1]
        x = x.view(-1, self.feature_size)  # B x N x D -> BN x D

        if x.device != self.clusters.device:
            msg = f"x.device {x.device} != cluster.device {self.clusters.device}"
            raise ValueError(msg)

        assignment = self.matmul_softmax.matmul_softmax_cuda(x, self.clusters)  # (BN x D) x (D x (K+G)) -> BN x (K+G)
        assignment = self.batch_norm(assignment)

        assignment = F.softmax(assignment, dim=1)  # BN x (K+G) -> BN x (K+G)
        # remove ghost assigments
        assignment = assignment[:, :self.cluster_size]
        assignment = assignment.view(-1, max_sample, self.cluster_size)  # -> B x N x K
        a_sum = th.sum(assignment, dim=1, keepdim=True)  # B x N x K -> B x 1 x K
        a = a_sum * self.clusters2

        assignment = assignment.transpose(1, 2)  # B x N x K -> B x K x N

        x = x.view(-1, max_sample, self.feature_size)  # BN x D -> B x N x D
        vlad = th.matmul(assignment, x)  # (B x K x N) x (B x N x D) -> B x K x D
        vlad = vlad.transpose(1, 2)  # -> B x D x K
        vlad = vlad - a

        # L2 intra norm
        vlad = F.normalize(vlad)

        # flattening + L2 norm
        vlad = vlad.reshape(-1, self.cluster_size * self.feature_size)  # -> B x DK
        vlad = F.normalize(vlad)
        return vlad  # B x DK
